def left(i):
    return 2 * i + 1

def right(i):
    return 2 * i + 2

def parent(i):
    return (i - 1) // 2

def is_max_heap(a):
    return all(a[parent(i)] >= a[i] for i in range(1, len(a)))

print(left(1), right(1), parent(4))
print(is_max_heap([16, 14, 10, 8, 7, 9, 3, 2, 4, 1]))
print(is_max_heap([16, 4, 10, 14, 7, 9, 3, 2, 8, 1]))

