static void heapify(int[] a, int i, int n) {
  int l = 2 * i + 1, r = 2 * i + 2, largest = i;
  if (l < n && a[l] > a[largest]) largest = l;
  if (r < n && a[r] > a[largest]) largest = r;
  if (largest != i) {
    int t = a[i]; a[i] = a[largest]; a[largest] = t;   // swap
    heapify(a, largest, n);                            // keep sinking
  }
}

