def heapify(a, i, n):
    while True:
        l, r = 2 * i + 1, 2 * i + 2
        largest = i
        if l < n and a[l] > a[largest]:
            largest = l
        if r < n and a[r] > a[largest]:
            largest = r
        if largest == i:
            return
        a[i], a[largest] = a[largest], a[i]
        i = largest

a = [16, 4, 10, 14, 7, 9, 3, 2, 8, 1]
heapify(a, 1, len(a))
print(a)

